+        return new CentroidState(CARTESIAN_ENCODER);
+    }
+
+    public static GroupingCentroidState initGrouping(BigArrays bigArrays) {
+        return new GroupingCentroidState(bigArrays, CARTESIAN_ENCODER);
+    }
